//! The apps Sora knows by their mark (both systems): notices and the chat history on Windows, the agents and chat
//! history pages everywhere (history.rs app_marks).

/// Apps whose notices get their own mark: the app's name, the words of its name or site, the official logo (Simple Icons, a
/// 24 x 24 outline that is filled), the brand colour, the colour of the logo on it, and whether it is a messenger. A messenger's
/// notice shows the contact's or group's picture with the logo as a small badge; any other app's notice shows the logo itself,
/// large, on a tile in the brand colour. Microsoft Copilot is not in that set, so a plain bubble stands in for it.
#[cfg_attr(not(win), allow(dead_code))] // `person`: Windows draws messenger notices itself.
pub(crate) struct Mark { pub name: &'static str, pub words: &'static [&'static str], pub path: &'static str, pub color: u32, pub fg: u32, pub person: bool }
