/// An app's own mark (Simple Icons outline on its brand colour), for the chat history page.
#[derive(serde::Serialize)]
pub struct MarkView { pub name: &'static str, pub path: &'static str, pub color: u32, pub fg: u32 }
pub fn marks() -> Vec<MarkView> { MARKS.iter().map(|m| MarkView { name: m.name, path: m.path, color: m.color, fg: m.fg }).collect() }
/// The app's name as shown, and whether it is an AI app ("ai") or a social one ("social").
pub fn app_info(label: &str) -> (String, &'static str) {
    const AI: [&str; 10] = ["ChatGPT", "Claude", "Perplexity", "Copilot", "Gemini", "Grok", "DeepSeek", "Mistral", "Qwen", "Kimi"];
    match mark_index(label) { Some(i) => (MARKS[i].name.to_string(), if AI.contains(&MARKS[i].name) { "ai" } else { "social" }), None => (label.to_string(), "social") }
}
/// Which mark an app or site goes with: its name (or the site's address) split into words, any of which may match.
pub(crate) fn mark_index(label: &str) -> Option<usize> {
    let l = label.to_lowercase();
    let words: Vec<&str> = l.split(|c: char| !c.is_alphanumeric()).filter(|w| !w.is_empty()).collect();
    MARKS.iter().position(|m| m.words.iter().any(|w| words.contains(w)))
}
